PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO settings(id,value) VALUES(1,'{"paused":true,"rules":[],"fields":{"체력":100,"관찰력":0,"소지금":0},"invites":{},"events":[],"dailyCap":1500}');
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, label TEXT NOT NULL, acct TEXT NOT NULL, token TEXT NOT NULL, cursor TEXT NOT NULL DEFAULT '', scan TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, error TEXT NOT NULL DEFAULT '', max_chars INTEGER NOT NULL DEFAULT 500);
CREATE TABLE IF NOT EXISTS oauth (state TEXT PRIMARY KEY, payload TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS participants (id TEXT PRIMARY KEY, acct TEXT NOT NULL UNIQUE, name TEXT NOT NULL, stats TEXT NOT NULL, inventory TEXT NOT NULL DEFAULT '{}', revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), actor_id TEXT NOT NULL, payload TEXT NOT NULL, created INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(state,created);
CREATE TABLE IF NOT EXISTS usage (rule_id TEXT NOT NULL, actor_id TEXT NOT NULL, day TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, last_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(rule_id,actor_id,day));
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id TEXT NOT NULL, created INTEGER NOT NULL, message TEXT NOT NULL, source TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_actor ON audit(actor_id,created DESC);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), body TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', due INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, first_attempt INTEGER, last_error TEXT NOT NULL DEFAULT '', posted_id TEXT, group_id TEXT NOT NULL DEFAULT '', title TEXT NOT NULL DEFAULT '봇 답글');
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(state,due);
CREATE TABLE IF NOT EXISTS locks (name TEXT PRIMARY KEY, owner TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runtime (key TEXT PRIMARY KEY, value TEXT NOT NULL);
